    /// <summary>
    /// associates a positive Case Number to each type of StepAP214 entity,
    /// given as a String defined in the EXPRESS form
    /// </summary>
    public override int CaseStep(string key)
    {
        // FMA - le 25-07-96 : Optimisation -> on teste en premier les types les plus
        //                     frequents dans le fichier cad geometry/topology
        int num = 0;
        if (key == Reco_CartesianPoint)
        {
            return 59; // car tres courant
        }
        if (THE_TYPENUMS.TryGetValue(key, out num))
        {
            return num;
        }
        if (THE_TYPESHOR.TryGetValue(key, out num))
        {
            return num; // AJOUT DES TYPES COURTS
        }
        return 0;
    }

