    public override void WriteStep(int cn, StepWriter sw, Transient ent)
    {
        if (cn == 0)
        {
            return;
        }
        switch (cn)
        {
            case 1:
                {
                    Address anent = ent as Address;
                    RWAddress tool = new RWAddress();
                    //      if (anent.IsNull()) return;
                    tool.WriteStep(sw, anent);
                }
                break;
            case 2:
                {
                    StepAdvancedBrepShapeRepresentation anent = ent as StepAdvancedBrepShapeRepresentation;
                    RWAdvancedBrepShapeRepresentation tool = new RWAdvancedBrepShapeRepresentation();
                    //      if (anent.IsNull()) return;
                    tool.WriteStep(sw, anent);
                }
                break;
            case 3:
                {
                    StepAdvancedFace anent = ent as StepAdvancedFace;
                    RWAdvancedFace tool = new RWAdvancedFace();
                    //      if (anent.IsNull()) return;
                    tool.WriteStep(sw, anent);
                }
                break;
            case 4:
                {
                    AnnotationCurveOccurrence anent = ent as AnnotationCurveOccurrence;
                    RWAnnotationCurveOccurrence tool = new RWAnnotationCurveOccurrence();
                    tool.WriteStep(sw, anent);
                }
                break;
            case 5:
                {
                    AnnotationFillArea anent = ent as AnnotationFillArea;
                    RWAnnotationFillArea tool = new RWAnnotationFillArea();
                    tool.WriteStep(sw, anent);
                }
                break;
            case 6:
                {
                    AnnotationFillAreaOccurrence anent = ent as AnnotationFillAreaOccurrence;
                    RWAnnotationFillAreaOccurrence tool = new RWAnnotationFillAreaOccurrence();
                    tool.WriteStep(sw, anent);
                }
                break;
            case 7:
                {
                    AnnotationOccurrence anent = ent as AnnotationOccurrence;
                    RWAnnotationOccurrence tool = new RWAnnotationOccurrence();
                    tool.WriteStep(sw, anent);
                }
                break;
            case 11:
                {
                    MappedItem anent = ent as MappedItem;
                    RWMappedItem tool = new RWMappedItem();
                    //      if (anent.IsNull()) return;
                    tool.WriteStep(sw, anent);
                }
                break;
            case 12:
                {
                    StyledItem anent = ent as StyledItem;
                    RWStyledItem tool = new RWStyledItem();
                    //      if (anent.IsNull()) return;
                    tool.WriteStep(sw, anent);
                }
                break;
            case 13:
                {
                    ApplicationContext anent = ent as ApplicationContext;
                    RWApplicationContext tool = new RWApplicationContext();
                    //      if (anent.IsNull()) return;
                    tool.WriteStep(sw, anent);
                }
                break;
            case 14:
                {
